SELECT *
FROM (

) content
WHERE 1 = 1


    AND content.resourceType = #{cursor.resourceType}



    AND content.moderationStatus = #{cursor.moderationStatus}



    AND (
        content.content LIKE CONCAT('%', #{cursor.keyword}, '%')
        OR content.authorLoginId LIKE CONCAT('%', #{cursor.keyword}, '%')
        OR content.authorNickname LIKE CONCAT('%', #{cursor.keyword}, '%')
    )



    AND (
        content.createdAt < #{cursor.cursorCreatedAt}
        OR (
            content.createdAt = #{cursor.cursorCreatedAt}
            AND content.resourceType > #{cursor.cursorResourceType}
    )
    OR (
            content.createdAt = #{cursor.cursorCreatedAt}
            AND content.resourceType = #{cursor.cursorResourceType}
            AND content.resourceId < #{cursor.cursorResourceId}
    )
    )


ORDER BY
    content.createdAt DESC,
    content.resourceType ASC,
    content.resourceId DESC
LIMIT #{cursor.size}

SELECT *
FROM (

) content
WHERE content.resourceType = #{resourceType}
    AND content.resourceId = #{resourceId}
